"""gl -- keyed green/red cells over a feature's value range, DETECTOR ONLY. Experimental (stand-in generators only).
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from ..prf import domain_id, prf_sign, prf_unit
from ._stats import z_to_p, stouffer


NAME = "gl"


def pair_stat(x: np.ndarray, key: bytes, col: str, delta: float):
    dom = domain_id("gl:" + col)
    u0 = float(prf_unit(key, dom, np.array([-1]))[0])
    j = np.floor(x / delta + u0).astype(np.int64)
    m = j >> 1
    um, inv = np.unique(m, return_inverse=True)
    ne = np.bincount(inv, weights=((j & 1) == 0), minlength=um.size)
    no = np.bincount(inv, weights=((j & 1) == 1), minlength=um.size)
    se, so = prf_sign(key, dom, um * 2), prf_sign(key, dom, um * 2 + 1)
    use = se != so
    d = (se * (ne - no))[use]
    den = float(np.sqrt(np.sum(d * d)))
    return (float(d.sum() / den) if den > 0 else 0.0), int(use.sum())


def detect(df: pd.DataFrame, key: bytes, columns: dict, **_):
    per, zs = {}, []
    for c, cp in columns.items():
        if c not in df.columns:
            per[c] = {"missing": True}
            continue
        x = df[c].to_numpy(dtype=np.float64)
        x = x[np.isfinite(x)]
        if x.size < 64:
            per[c] = {"skipped": True}
            continue
        z, npairs = pair_stat(x, key, c, cp["delta"])
        per[c] = {"z": z, "n": int(x.size), "pairs": npairs, "p": z_to_p(z), "tests": 1}
        zs.append(z)
    z = stouffer(zs)
    return {"method": NAME, "columns": per, "z": z, "p": z_to_p(z) if zs else 1.0}
